/**
 * Compares the supported repository size path with statement enumeration.
 *
 * Run with JMH's {@code -prof gc} to compare allocation per operation as well as time.
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
@Fork(1)
@Threads(1)
public class LmdbStatementCountBenchmark {

	@Param({ "10000", "100000" })
	public int statementCount;

	private File dataDir;
	private SailRepository repository;
	private RepositoryConnection connection;

	@Setup(Level.Trial)
	public void setUp() {
		dataDir = Files.newTemporaryFolder();
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();

		ValueFactory valueFactory = repository.getValueFactory();
		IRI predicate = valueFactory.createIRI("urn:count-benchmark:predicate");
		Resource context = valueFactory.createIRI("urn:count-benchmark:context");
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.begin();
			for (int i = 0; i < statementCount; i++) {
				writer.add(valueFactory.createIRI("urn:count-benchmark:subject:" + i), predicate,
						valueFactory.createLiteral(Integer.toString(i)), context);
			}
			writer.commit();
		}
		connection = repository.getConnection();
	}

	@TearDown(Level.Trial)
	public void tearDown() {
		try {
			if (connection != null) {
				connection.close();
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
			if (dataDir != null) {
				LmdbTestUtil.deleteDir(dataDir);
			}
		}
	}

	@Benchmark
	public long repositorySize() {
		return connection.size();
	}

	@Benchmark
	public long enumerateStatements() {
		long count = 0;
		try (RepositoryResult<Statement> statements = connection.getStatements(null, null, null)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}
}
